import type { IsoTimestamp, OrgId, UserId } from "./common";

/** `read` tokens act as a viewer; `write` tokens carry the member's live role. */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as the app sees it. Deliberately carries neither the
 * secret nor its hash — the secret is returned once, from `createApiToken`,
 * and the hash never leaves the repository layer.
 */
export interface ApiToken {
  id: string;
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  /** First 12 characters of the secret, so a user can tell tokens apart. */
  prefix: string;
  expiresAt: IsoTimestamp;
  lastUsedAt: IsoTimestamp | null;
  revokedAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
}
EOF
cat > src/schemas/api-token.ts <<'EOF'
import { z } from "zod";
import { orgIdSchema } from "./common";

export const apiTokenScopeSchema = z.enum(["read", "write"]);

export const createApiTokenSchema = z.object({
  orgId: orgIdSchema,
  name: z.string().trim().min(1).max(80),
  scope: apiTokenScopeSchema,
  expiresInDays: z.number().int().min(1).max(365),
});

export type CreateApiTokenInput = z.input<typeof createApiTokenSchema>;
EOF
