/**
 * Personal API tokens. Only the hash of the secret is stored; rows are never
 * deleted, only revoked.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import type { ApiTokenRow } from "@/server/db";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

/** A token row with its hash, for the one lookup that needs it. */
export interface StoredApiToken {
  readonly apiToken: ApiToken;
  readonly tokenHash: string;
}

export interface NewApiToken {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

function toApiToken(row: ApiTokenRow): ApiToken {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    name: row.name,
    scope: row.scope,
    prefix: row.prefix,
    expiresAt: brandStamp(row.expiresAt),
    lastUsedAt: brandStampOrNull(row.lastUsedAt),
    revokedAt: brandStampOrNull(row.revokedAt),
    createdAt: brandStamp(row.createdAt),
  };
}

/**
 * Inserts the token unless the user already holds `limit` usable (unrevoked,
 * unexpired at `input.createdAt`) tokens in the org; returns `null` then. The
 * count and the insert share one synchronous transaction so concurrent calls
 * cannot both slip under the limit.
 */
export function insertApiTokenWithinLimit(
  input: NewApiToken,
  limit: number,
): ApiToken | null {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, input.orgId),
          eq(apiTokens.userId, input.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, input.createdAt),
        ),
      )
      .get();

    if ((usable?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: input.orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        prefix: input.prefix,
        tokenHash: input.tokenHash,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: input.createdAt,
        updatedAt: input.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

/** Every token the user holds in the org, revoked and expired included, newest first. */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), desc(sql`rowid`))
    .all();
  return rows.map(toApiToken);
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Authentication runs before any org is known, so like the invitation accept
 * flow this read is keyed on the hash alone — it carries the tenant with it.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Revokes the token if it is still live; `null` when it was already revoked. */
export async function markApiTokenRevoked(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

/** Revokes every live token the user holds in the org; returns those it changed. */
export async function revokeApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all();
  return rows.map(toApiToken);
}

/** Stamps a successful use; only touches a token that is still unrevoked. */
export async function touchApiTokenLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .run();
}
EOF
