/** Usable (unrevoked, unexpired) tokens one user may hold per organization. */
export const MAX_USABLE_TOKENS_PER_USER = 5;

const TOKEN_PREFIX = "tfk_";
const DISPLAY_PREFIX_LENGTH = 12;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

export class ApiTokenLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(readonly limit: number) {
    super(`You can hold at most ${limit} active API tokens in this organization`);
    this.name = "ApiTokenLimitError";
  }
}

/**
 * Issues a token and returns its secret — the only time the secret is ever
 * available; only its hash is stored.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const token = `${TOKEN_PREFIX}${randomToken()}`;
  const now = new Date();

  const apiToken = apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS_PER_USER,
  );

  if (apiToken === null) {
    throw new ApiTokenLimitError(MAX_USABLE_TOKENS_PER_USER);
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

/** A user's tokens in one org, revoked and expired included, newest first. */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokensForUser(orgId, userId);
}

