 * Revokes one token. Idempotent: an already-revoked token comes back as it
 * is, and no second audit row is written.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.markApiTokenRevoked(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  if (revoked === null) {
