export async function revokeApiTokensForRemovedMember(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);

  const revoked = await apiTokenRepo.revokeApiTokensForUser(
    orgId,
    userId,
    toIsoTimestamp(new Date()),
  );
  for (const apiToken of revoked) {
    await emitRevoked(actor, apiToken);
  }
  return revoked;
}

