 * Resolves a presented secret to the `Actor` it acts as, or `null`. A `read`
 * token always acts as a viewer; a `write` token takes the member's role as
 * it stands now. Only a successful call stamps `lastUsedAt`.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  if (typeof token !== "string" || !token.startsWith(TOKEN_PREFIX)) return null;

  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (apiToken === null || apiToken.revokedAt !== null) return null;

  const now = new Date();
  if (now.getTime() >= Date.parse(apiToken.expiresAt)) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(apiToken.orgId, apiToken.userId);
  if (member === null || member.status !== "active") return null;

  await apiTokenRepo.touchApiTokenLastUsed(
    apiToken.orgId,
    apiToken.id,
    toIsoTimestamp(now),
  );

  return {
    userId: apiToken.userId,
    orgId: apiToken.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

async function emitRevoked(actor: Actor, apiToken: ApiToken): Promise<void> {
  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
  });
}
