import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { ZodError } from "zod";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as svc from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { registerEventHandlers } from "@/server/services/event-registry";
import { activityFilterSchema } from "@/schemas/activity";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("api tokens", () => {
  it("works end to end", async () => {
    const t = await createTenant("tok1");
    const o = await createTenant("tok2");
    const m = t.actors.member;
    await expect(svc.createApiToken(m, { orgId: t.org.id, name: " ", scope: "read", expiresInDays: 1 })).rejects.toBeInstanceOf(ZodError);
    await expect(svc.createApiToken(m, { orgId: o.org.id, name: "x", scope: "read", expiresInDays: 1 })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(svc.createApiToken(t.actors.viewer, { orgId: t.org.id, name: "x", scope: "write", expiresInDays: 1 })).rejects.toBeInstanceOf(PermissionDeniedError);
    const created = [];
    for (let i = 0; i < 5; i++) created.push(await svc.createApiToken(m, { orgId: t.org.id, name: `t${i}`, scope: i ? "read" : "write", expiresInDays: 30 }));
    expect(created[0].token.startsWith("tfk_")).toBe(true);
    expect(created[0].apiToken.prefix).toBe(created[0].token.slice(0, 12));
    await expect(svc.createApiToken(m, { orgId: t.org.id, name: "six", scope: "read", expiresInDays: 30 })).rejects.toBeTruthy();
    const list = await svc.listApiTokens(m, t.org.id);
    expect(list.map((x) => x.name)).toEqual(["t4", "t3", "t2", "t1", "t0"]);
    await expect(svc.listApiTokens(m, t.org.id, t.userIds.admin)).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await svc.listApiTokens(t.actors.admin, t.org.id, m.userId)).toHaveLength(5);

    const actor = await svc.authenticateApiToken(created[0].token);
    expect(actor).toEqual({ userId: m.userId, orgId: t.org.id, role: "member" });
    expect((await svc.authenticateApiToken(created[1].token))?.role).toBe("viewer");
    expect(await svc.authenticateApiToken("tfk_nope")).toBeNull();

    const r = await svc.revokeApiToken(m, t.org.id, created[1].apiToken.id);
    expect(r.revokedAt).not.toBeNull();
    const r2 = await svc.revokeApiToken(t.actors.owner, t.org.id, created[1].apiToken.id);
    expect(r2.revokedAt).toBe(r.revokedAt);
    expect(await svc.authenticateApiToken(created[1].token)).toBeNull();
    await svc.createApiToken(m, { orgId: t.org.id, name: "six", scope: "read", expiresInDays: 30 });

    vi.useFakeTimers({ now: new Date(Date.now() + 31 * 86400000), toFake: ["Date"] });
